106	  };
107	  fields: {
108	    heading: string;
109	    readonly links: ReadonlyArray<LinkEntry>;
110	    /**
111	     * Renders the contact-channel icon row beneath this group's links.
112	     *
113	     * A flag rather than matching the heading text: `heading` is a localised Contentful
114	     * value, so `heading === 'Contact'` silently stops matching the moment an editor writes
115	     * "Kontakt" or "Contacto" — and this footer ships to eight storefronts.
116	     */
117	    showContactChannels?: boolean;
