130	    // Read-only both ways. The footer only ever .maps these, but footer/index.stories.content.ts's
131	    // FOOTER_FIXTURE is a plain module singleton multiple stories in index.stories.tsx read
132	    // directly, so an in-place push/sort/index-assign anywhere would corrupt every other
133	    // story reading the same object. ReadonlyArray blocks push/pop/splice/sort/reverse/
134	    // index-assign/length; the `readonly` property modifier additionally blocks swapping the
135	    // whole array out. Matches BottomBarProps.legalLinks in footer/index.tsx, which already
136	    // types its array as ReadonlyArray<>.
137	    readonly navGroups: ReadonlyArray<FooterNavGroupEntry>;
138	    readonly legalLinks?: ReadonlyArray<LinkEntry>;
139	    copyrightOwner?: string;
140	    phoneHref?: string;
141	    whatsAppHref?: string;
142	    emailHref?: string;
143	    /**
144	     * Regions this footer applies to. Omitted/empty = the default/global footer for its
